mapper.insert:
INSERT /* SQL_ID: CollectionLogMapper.insertCollectionLog */
INTO dtmeta.tb_meta_collectionlog (
      colec_log_id
    , colec_log_regr_id
    , colec_log_regr_nm
    , colec_log_reg_dt
    , colec_log_data
) VALUES(
      #{colecLogId}
    , #{colecLogRegrId}
    , #{colecLogRegrNm}
    , current_timestamp
    , #{colecLogData}::jsonb
)

mapper.select:
SELECT EXISTS (  /* SQL_ID: CollectionLogMapper.isLogExist */
    SELECT 1
    FROM dtmeta.tb_meta_collectionlog
    WHERE colec_log_id = #{colecLogId}
)
